'use strict';
const BANK=JSON.parse(document.getElementById('bank').textContent);
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const day=t=>new Date(t).toLocaleDateString('sv-SE');const nowDay=()=>day(Date.now());
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const equal=(a,b)=>a.length===b.length&&[...new Set(a)].sort((x,y)=>x-y).every((v,i)=>v===[...new Set(b)].sort((x,y)=>x-y)[i]);
function grade(selected,expected){const a=[...new Set(selected)],b=[...new Set(expected)],missing=b.filter(x=>!a.includes(x)),extra=a.filter(x=>!b.includes(x));return {correct:!!b.length&&equal(a,b),missing,extra,kind:!a.length?'未作答':missing.length&&extra.length?'漏选并多选':missing.length?'漏选':extra.length?'多选':'全对'};}
function shuffle(values){const a=[...values];for(let i=a.length-1;i>0;i--){const n=new Uint32Array(1);if(globalThis.crypto?.getRandomValues)crypto.getRandomValues(n);else n[0]=Math.random()*4294967296;const j=n[0]%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a;}
function summarize(attempts){let streak=0;const dates=new Set();for(let i=attempts.length-1;i>=0;i--){if(!attempts[i].data.correct||attempts[i].data.unsure)break;streak++;dates.add(day(attempts[i].ts));}const everWrong=attempts.some(e=>!e.data.correct);return {streak,mastered:streak>=3&&dates.size>=2,everWrong};}
window.ArtCore={grade,equal,summarize,shuffle};
let store={events:[],session:null,cloud:{cursor:0,userId:null},settings:{shuffle:true,minutes:20}},db=null,persistTimer=null,saveError=false;
let tab='home',viewPage=1,filterChapter='all',filterTag='all',filterSearch='',filterWrong='active',filterYear='all',filterExam='all',syncing=false,syncText='本地保存',syncTimer=null,installEvent=null;
let byId=new Map(),derived=new Map(),allQuestions=[];
const allowedEvents=new Set(['attempt','favorite','note','correction','issue','tag','legacywrong','custom','familiar','reading','sourceReview']);
const bounded=(promise,ms=4000)=>Promise.race([promise,new Promise((_,reject)=>setTimeout(()=>reject(Error('存储响应超时')),ms))]);
async function load(){
 let expired=false;
 try{db=await bounded(new Promise((resolve,reject)=>{const r=indexedDB.open('zju-art-choice',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('state'))r.result.createObjectStore('state')};r.onsuccess=()=>{if(expired){r.result.close();return}resolve(r.result)};r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('存储被其他窗口占用'))}));const old=await bounded(new Promise((resolve,reject)=>{const tx=db.transaction('state');const r=tx.objectStore('state').get('main');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);tx.onabort=()=>reject(tx.error)}));if(old)store={...store,...old,settings:{...store.settings,...old.settings},cloud:{...store.cloud,...old.cloud}};}
 catch{expired=true;if(db)db.close();db=null;try{const old=JSON.parse(localStorage.getItem('zju-art-choice-fallback')||'null');if(old)store={...store,...old};}catch{}toast('本地存储暂不可用，已切换备用保存；原记录未删除，请联网同步或导入备份');}
}
async function persist(){
 try{if(db)await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(JSON.parse(JSON.stringify(store)),'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});else localStorage.setItem('zju-art-choice-fallback',JSON.stringify(store));saveError=false;}
 catch{saveError=true;toast('本地保存失败，请立即导出备份，避免丢失本次记录');}
}
function save(){void persist();}
function emit(type,qid,data,id=uid()){if(store.events.some(e=>e.id===id))return;store.events.push({id,type,qid,data,ts:Date.now(),_synced:false});save();rebuild();scheduleSync();}
function rebuild(){
 const custom=new Map();for(const e of [...store.events].sort((a,b)=>a.ts-b.ts||a.id.localeCompare(b.id)))if(e.type==='custom'&&validQuestion(e.data.question))custom.set(e.qid,e.data.question);
 byId=new Map(BANK.questions.map(q=>[q.id,q]));allQuestions=[...byId.values()];derived=new Map();
 for(const q of allQuestions)derived.set(q.id,{attempts:[],favorite:false,note:'',tag:'',correction:null,issue:false,legacywrong:false,manualFamiliar:false,resetAt:0});
 for(const e of [...store.events].sort((a,b)=>a.ts-b.ts||a.id.localeCompare(b.id))){const d=derived.get(e.qid);if(!d)continue;if(e.type==='attempt'){d.attempts.push(e);if(!e.data.correct||e.data.unsure)d.manualFamiliar=false}else if(e.type==='familiar'){d.manualFamiliar=!!e.data.value;if(!e.data.value)d.resetAt=e.ts}else if(e.type==='favorite')d.favorite=!!e.data.value;else if(e.type==='note')d.note=String(e.data.value||'');else if(e.type==='tag')d.tag=String(e.data.value||'');else if(e.type==='correction')d.correction=e.data;else if(e.type==='issue')d.issue=!!e.data.value;else if(e.type==='legacywrong')d.legacywrong=true;}
 for(const [id,d] of derived){Object.assign(d,summarize(d.attempts.filter(e=>e.ts>d.resetAt)));d.everWrong=d.attempts.some(e=>!e.data.correct);d.familiar=d.manualFamiliar||d.mastered;d.last=d.attempts[d.attempts.length-1];d.wrong=(d.everWrong||d.legacywrong)&&!d.familiar;d.uncertain=!d.familiar&&!!d.last?.data.unsure;const span=d.last?.data.correct?([1,1,3,7,14,30][Math.min(d.streak,5)]*86400000):600000;d.due=!d.familiar&&!!d.last&&d.last.ts+span<=Date.now();}
}
function markFamiliar(id,value){const q=byId.get(id);if(!q)return;for(const related of allQuestions.filter(x=>x.group===q.group))emit('familiar',related.id,{value});}
const correctionFor=q=>{const c=derived.get(q.id)?.correction;if(!c)return null;if(c.questionRevision)return c.questionRevision===q.revision?c:null;if(c.bankVersion===BANK.version)return c;const compatibility=BANK.correctionCompatibility;return compatibility?.versions.includes(c.bankVersion)&&compatibility.revisions[q.id]===q.revision?c:null};
const answerFor=q=>correctionFor(q)?.answers||q.answers;
const pending=q=>derived.get(q.id)?.issue||((q.status==='pending'||!q.answers.length)&&!correctionFor(q));
const badgeFor=q=>pending(q)?'<span class="badge warn">待核对 · 不计分</span>':correctionFor(q)?'<span class="badge">本版个人教材核对</span>':q.status==='textbook'?'<span class="badge">教材对应参考答案</span>':'<span class="badge">原题库参考答案</span>';
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);}
function dialog(content){$('#dialogBody').innerHTML=content;$('#dialog').showModal();}
$('#closeDialog').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});
function setTab(name){tab=name;viewPage=1;filterSearch='';filterChapter='all';filterTag='all';filterYear='all';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));render();window.scrollTo({top:0});}
$$('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$('.brand').onclick=e=>{e.preventDefault();setTab('home')};
function head(title,sub){return '<div class="topline"><div><h1>'+title+'</h1><p>'+sub+'</p></div><span class="date">'+new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})+'</span></div>';}
function stats(){const ds=[...derived.values()],attempts=ds.flatMap(d=>d.attempts),today=attempts.filter(e=>day(e.ts)===nowDay());return {touched:ds.filter(d=>d.attempts.length).length,mastered:ds.filter(d=>d.familiar).length,wrong:ds.filter(d=>d.wrong).length,due:ds.filter(d=>d.due||d.uncertain).length,today:today.length,correct:today.filter(e=>e.data.correct).length,attempts};}
function home(){
 const s=stats(),chapters=[...new Map(BANK.questions.filter(q=>q.chapterId!=='exam').map(q=>[q.chapterId,q.chapter])).entries()];
 return head('艺术学概论','教材重编 '+BANK.meta.bankCount+' 题 · 回忆真题 '+BANK.meta.examCount+' 题 · 第五版原书口径')+
 '<section class="panel"><div class="actions">'+(store.session&&!store.session.finished?'<button data-resume class="primary">继续上次训练</button>':'')+'<button data-start="smart">综合练习20题</button><button data-start="wrong">错题再练 '+s.wrong+'</button><button data-exam-settings>10题模拟卷</button><button data-open-guide>总指南</button></div><p class="muted">已练 '+s.touched+' 题 · 已熟悉/巩固 '+s.mastered+' 题 · 到期复习 '+s.due+' 题</p></section>'+
 '<div class="section-title"><h2>章节训练</h2><small>点选章节，自设题量</small></div><div class="chapter-grid">'+chapters.map(([id,title],i)=>{const qs=allQuestions.filter(q=>q.chapterId===id),n=qs.filter(q=>derived.get(q.id).familiar).length;return '<button class="chapter" data-chapter-start="'+id+'"><span class="num">'+(i+1)+'</span><b>'+esc(title.replace(/^第.+?章\s*/,''))+'</b><small>'+qs.length+'题 · '+n+'题已熟悉</small></button>'}).join('')+'</div><p class="muted">默认跳过已熟悉考点，同轮不重复抽同考点变式。真题按原貌保留，待核定题不计分。</p>';
}
function guidePage(){return head('浙大选择题总指南','基于本地2022—2026年50道回忆题分析；可展开章节阅读。')+'<button data-book-audit>全书37节核查与逐段回忆</button><div class="guide">'+(location.protocol==='file:'?BANK.strategyHtml.split('./coverage.html').join('./全书考点核查.html'):BANK.strategyHtml)+'</div><p><a href="'+(location.protocol==='file:'?'./浙大选择题总指南.html':'./guide.html')+'" target="_blank" rel="noopener">单独打开 / 打印指南</a></p>';}
function readingStates(){const map=new Map();for(const e of [...store.events].filter(e=>e.type==='reading').sort((a,b)=>a.ts-b.ts||a.id.localeCompare(b.id)))map.set(e.qid,!!e.data.value);return map;}
function auditPage(){const a=BANK.bookAudit;if(!a)return head('全书核查','尚无核查清单');const states=readingStates(),done=[...states.values()].filter(Boolean).length;return head('全书核查与逐段回忆','12章37节 · 正文443页 · 阅读自测与计分配题分别记录')+'<section class="panel"><p>已可复述 '+done+' / '+a.readingUnitCount+' 段。逐段回忆覆盖全文；计分题目前定位到 '+a.questionSourcePages+' 页。没有计分题的页明确保留查漏入口。</p><p class="muted">先遮住原文，复述定义、分类、人物作品与例证关系，再展开对照。文字用于辅助定位，疑字以扫描页为准；复述记录不算选择题答对。</p><label>跳到PDF页 <input id="auditPageNumber" type="number" min="7" max="449" value="7" style="width:90px"></label> <button data-read-jump>打开该页</button><p>引论：'+a.introPages.map(n=>'<button data-read-page="'+n+'">'+n+'页</button>').join(' ')+'</p></section>'+a.sections.map(s=>'<details class="panel audit-section"><summary><b>第'+s.chapter+'章 · '+esc(s.title)+'</b><small> · '+s.questionIds.length+'道配题索引 · PDF '+s.start+'—'+s.end+'页</small></summary><p>'+esc(s.topics.join('；'))+'</p><button data-section-practice="'+s.id+'">自选题量练本节</button><div class="actions">'+a.pages.filter(x=>x.page>=s.start&&x.page<=s.end).map(x=>{const units=a.readingUnits[String(x.page)]||[],known=units.filter(u=>states.get(u.id)).length;return '<button data-read-page="'+x.page+'">'+x.page+'页 · '+known+'/'+units.length+'段 · '+(x.questionIds.length?'有配题':'待查漏')+'</button>'}).join('')+'</div></details>').join('');}
function readBookPage(n){if(!Number.isInteger(n)||n<7||n>449){toast('请输入7到449之间的PDF页码');return}const a=BANK.bookAudit,units=a.readingUnits[String(n)]||[],states=readingStates(),row=a.pages.find(x=>x.page===n);const image=(location.protocol==='file:'?'./辅助资料/教材页面/':'./book-pages/')+'教材-'+String(n).padStart(3,'0')+'.jpg';dialog('<h2>PDF第'+n+'页 · 逐段回忆</h2><p>各段先自行复述，再展开原文核对。扫描页是最终依据；自评不计选择题得分。</p><p><a href="'+image+'" target="_blank" rel="noopener">打开教材扫描页</a></p><div class="actions">'+(n>7?'<button data-read-page="'+(n-1)+'">上一页</button>':'')+(n<449?'<button data-read-page="'+(n+1)+'">下一页</button>':'')+(row.questionIds.length?'<button data-page-practice="'+n+'">练本页配题</button>':'<span class="badge warn">本页暂未有计分配题，须回读查漏</span>')+'</div>'+units.map((u,i)=>'<section><h3>第'+(i+1)+'段 · '+(states.get(u.id)?'已能复述':'待复述')+'</h3><p class="muted">提示：'+esc(u.text.slice(0,18))+'…</p><details><summary>复述后展开原文</summary><p class="note-text">'+esc(u.text)+'</p></details><button data-reading-unit="'+u.id+'" data-reading-page="'+n+'">'+(states.get(u.id)?'改为还需复习':'标记已能复述')+'</button></section>').join(''));}
function sectionPractice(id){const s=BANK.bookAudit.sections.find(x=>x.id===id);if(!s)return;const pool=s.questionIds.map(x=>byId.get(x)).filter(Boolean);dialog('<h2>'+esc(s.title)+'</h2><label class="check-row"><input id="sectionFamiliar" type="checkbox">包含熟悉题</label><p id="sectionAvailable"></p><label>本轮题量 <input id="sectionCount" type="number" min="1" value="10"></label><button id="beginSection">开始练习</button>');const refresh=()=>{const n=candidates('chapter','ch'+s.chapter,pool,$('#sectionFamiliar').checked).length;$('#sectionAvailable').textContent='当前可练 '+n+' 个考点';$('#sectionCount').max=Math.max(1,n);$('#sectionCount').value=n?Math.max(1,Math.min(n,Number($('#sectionCount').value)||10)):0;$('#beginSection').disabled=!n};$('#sectionFamiliar').onchange=refresh;refresh();$('#beginSection').onclick=()=>{const n=Number($('#sectionCount').value),max=Number($('#sectionCount').max);if(!Number.isInteger(n)||n<1||n>max){toast('请输入有效题量');return}const include=$('#sectionFamiliar').checked;$('#dialog').close();start('chapter','ch'+s.chapter,pool,n,include)};}

function familiarControl(q){const d=derived.get(q.id);return '<button data-familiar="'+esc(q.id)+'">'+(d.familiar?'取消熟悉':'标为已熟悉')+'</button>';}
function row(q,context='library'){
 const d=derived.get(q.id);return '<article class="list-row"><div class="rowtop"><div>'+badgeFor(q)+(d.favorite?'<span class="badge">已收藏</span>':'')+(d.familiar?'<span class="badge">'+(d.manualFamiliar?'已熟悉':'已巩固')+'</span>':'')+'<h3>'+esc(q.q)+'</h3><p>'+esc(q.chapter)+' · '+(q.year?'回忆真题第'+q.number+'题':esc(q.tags?.join(' / ')||'基础题'))+'</p><p>'+(d.attempts.length?'已练 '+d.attempts.length+' 次 · 连续全对 '+d.streak+' 次'+(d.last?' · 最近 '+esc(d.last.data.kind):''):'尚未练习')+(d.tag?' · '+esc(d.tag):'')+'</p></div><button data-practice-one="'+esc(q.id)+'">'+(pending(q)?'去核对':'练一题')+'</button></div>'+(q.flags?.length?'<p class="danger">'+esc(q.flags.join('；'))+'</p>':'')+'<div class="list-actions">'+familiarControl(q)+'<button data-fav="'+esc(q.id)+'">'+(d.favorite?'取消收藏':'收藏')+'</button><button data-note="'+esc(q.id)+'">'+(d.note?'编辑笔记':'记笔记')+'</button><button data-evidence="'+esc(q.id)+'">教材原文</button><button data-correct="'+esc(q.id)+'">核对答案</button></div></article>';
}
function chapterFilter(){return '<select id="chapterFilter" aria-label="筛选章节"><option value="all">全部章节</option>'+[...new Map(allQuestions.map(q=>[q.chapterId,q.chapterId==='exam'?'历年真题':q.chapter])).entries()].map(([id,n])=>'<option value="'+id+'" '+(filterChapter===id?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select>';}
function pager(total){return '<div class="pagination"><button data-page="'+(viewPage-1)+'" '+(viewPage===1?'disabled':'')+'>上一页</button><span>'+viewPage+' / '+Math.max(1,Math.ceil(total/20))+' · '+total+' 题</span><button data-page="'+(viewPage+1)+'" '+(viewPage*20>=total?'disabled':'')+'>下一页</button></div>';}
function filtered(q){return (filterChapter==='all'||q.chapterId===filterChapter)&&(!filterSearch||(q.q+q.options.join('')+q.explain+(derived.get(q.id)?.note||'')).toLowerCase().includes(filterSearch.toLowerCase()));}
function library(){
 const base=allQuestions.filter(filtered).filter(q=>filterTag==='all'||filterTag==='familiar'&&derived.get(q.id).familiar||filterTag==='pending'&&pending(q)||filterTag==='favorite'&&derived.get(q.id).favorite||filterTag==='unseen'&&!derived.get(q.id).attempts.length);
 return head('全部题库','教材核定新版：未核定旧题已归档，支持逐项依据、熟悉标记和备份。')+'<div class="filters"><input id="search" aria-label="搜索题目" placeholder="搜索题干、作品、人物、笔记…" value="'+esc(filterSearch)+'">'+chapterFilter()+'<select id="tagFilter" aria-label="筛选题目状态">'+[['all','全部题目'],['unseen','尚未练习'],['familiar','已熟悉 / 已巩固'],['favorite','我的收藏'],['pending','待核对']].map(([v,n])=>'<option value="'+v+'" '+(filterTag===v?'selected':'')+'>'+n+'</option>').join('')+'</select><button data-start-filter>练习当前筛选</button></div><section class="panel">'+(base.length?base.slice((viewPage-1)*20,viewPage*20).map(q=>row(q)).join(''):'<div class="empty">没有匹配的题目</div>')+'</section>'+pager(base.length);
}
function wrong(){
 const modes=[['active','待攻克'],['due','到期复习'],['uncertain','拿不准'],['mastered','已熟悉 / 已巩固'],['all','曾经错过']];const qs=allQuestions.filter(filtered).filter(q=>{const d=derived.get(q.id);return filterWrong==='active'?d.wrong:filterWrong==='due'?d.due:filterWrong==='uncertain'?d.uncertain:filterWrong==='mastered'?d.familiar:d.everWrong||d.legacywrong;});
 return head('错题不是终点，是下一轮的起点。','连续3次完整答对，且至少跨2个日期，才计入已巩固。')+'<div class="chips">'+modes.map(([v,n])=>'<button class="chip '+(filterWrong===v?'active':'')+'" data-wrong-filter="'+v+'">'+n+'</button>').join('')+'</div><div class="filters">'+chapterFilter()+'<input id="search" aria-label="搜索错题" placeholder="搜索错题或笔记" value="'+esc(filterSearch)+'"><button data-wrong-start class="primary">练习这组错题</button></div><div class="panel">'+(qs.length?qs.slice((viewPage-1)*20,viewPage*20).map(q=>row(q,'wrong')).join(''):'<div class="empty"><b>这里暂时没有题目</b>完成训练后，漏选、多选和拿不准的题会自动归入对应队列。</div>')+'</div>'+pager(qs.length);
}
function exams(){
 let qs=allQuestions.filter(q=>q.origin==='真题回忆整理'&&(filterYear==='all'||q.year===Number(filterYear))&&filtered(q));if(filterExam==='pending')qs=allQuestions.filter(pending).filter(filtered);
 return head('真题看规律，存疑题回到原文。','完整收录2022—2026年50道回忆题；核定答案为教材对应参考答案，缺项或疑义题暂不计分。')+'<div class="chips"><button class="chip '+(filterExam==='all'?'active':'')+'" data-exam-filter="all">历年回忆真题</button><button class="chip '+(filterExam==='pending'?'active':'')+'" data-exam-filter="pending">全部待核对 '+allQuestions.filter(pending).length+'</button><button data-guide>出题观察与复习方法</button></div><div class="filters">'+(filterExam==='all'?'<select id="yearFilter" aria-label="真题年份"><option value="all">全部年份</option>'+[2022,2023,2024,2025,2026].map(y=>'<option '+(String(y)===filterYear?'selected':'')+'>'+y+'</option>').join('')+'</select>':chapterFilter())+'<input id="search" placeholder="搜索真题或疑点" aria-label="搜索真题" value="'+esc(filterSearch)+'"></div><div class="callout">本版以第五版原书为范围，教材重编题提供逐项理由及扫描页。回忆真题不是官方答案，其他年份缺失考点不能据此认定不考。</div><div class="panel">'+qs.slice((viewPage-1)*20,viewPage*20).map(q=>row(q)).join('')+'</div>'+pager(qs.length);
}
function dataPage(){const s=stats();return head('学习记录，跟着你走。','无需登录，支持离线训练与备份迁移。')+'<div class="grid2"><section class="panel"><h2>独立离线版</h2><p>无需登录。首次联网打开并缓存后，可从主屏幕离线刷题。记录保存在当前设备，跨设备请导出、导入备份。教材图片查看后单独缓存。</p></section><section class="panel"><span class="eyebrow">BACKUP</span><h2>备份与迁移</h2><p class="muted">导出后可在另一台设备导入。也可导入原学习台“导出数据”生成的JSON，保留旧题的原始记录；未核定的导入题不会重新进入训练池。</p><div class="actions"><button data-export class="primary">导出学习备份</button><button data-import>导入 / 合并记录</button><button data-export-wrong>导出错题</button></div><p class="muted">导入采用合并方式，不删除现有记录。</p></section></div><section class="panel"><h2>训练设置</h2><label class="check-row"><input type="checkbox" id="shuffleSetting" '+(store.settings.shuffle?'checked':'')+'>练习时打乱选项顺序，避免记住固定答案字母</label><label class="field"><span>模拟卷自设训练时长（分钟）</span><input id="minutesSetting" type="number" min="1" max="120" value="'+store.settings.minutes+'"><small>仅用于训练，不是考试官方分配时长。</small></label><p class="muted">所有题均为不定项，不显示正确选项个数；只有完整选对才计分。</p></section><section class="panel guide"><h2>题库与核对范围</h2><p>教材重编 '+BANK.meta.bankCount+' 题 + 教材对应回忆题 '+BANK.meta.examCount+' 题，共 '+BANK.questions.length+' 题。其中 '+BANK.meta.pendingCount+' 道回忆题待核对，不计分。旧版未核定学习台题保留本地归档。</p><p>'+esc(BANK.meta.sourceNote)+'</p><p>重编题采用书内干扰，正确项数量不固定；真实回忆题不人为改动答案数量。同一轮按考点去重。已练覆盖 '+s.touched+' 题、已巩固 '+s.mastered+' 题，均不等同于考试满分保证。</p><button data-guide>阅读复习方法</button></section>';}
function render(){if(tab==='practice'){renderPractice();return}$('#main').innerHTML=tab==='home'?home():tab==='wrong'?wrong():tab==='library'?library():tab==='exams'?exams():tab==='guide'?guidePage():tab==='audit'?auditPage():tab==='sourcebank'?sourceBankPage():dataPage();if(tab==='home')$('#main').insertAdjacentHTML('beforeend','<section class="panel"><button data-source-bank>网盘题库 · 选择 / 填空</button><button data-book-audit>全书核查 · 37节配题 / 逐段回忆</button><p class="muted">按原书逐节查漏，复述记录也可备份。</p></section>');$('#bankSummary').textContent=BANK.questions.length+' 题 · 12章 · 不定项';bindFilters();}
function bindFilters(){if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;filterSearch=e.target.value;viewPage=1;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#chapterFilter'))$('#chapterFilter').onchange=e=>{filterChapter=e.target.value;viewPage=1;render()};if($('#tagFilter'))$('#tagFilter').onchange=e=>{filterTag=e.target.value;viewPage=1;render()};if($('#yearFilter'))$('#yearFilter').onchange=e=>{filterYear=e.target.value;viewPage=1;render()};if($('#shuffleSetting'))$('#shuffleSetting').onchange=e=>{store.settings.shuffle=e.target.checked;save()};if($('#minutesSetting'))$('#minutesSetting').onchange=e=>{store.settings.minutes=Math.max(1,Math.min(120,Number(e.target.value)||20));save()};}
function candidates(mode,chapter='all',specific=null,includeFamiliar=false){
 let qs=(specific||allQuestions).filter(q=>!pending(q)&&(chapter==='all'||q.chapterId===chapter));
 const familiarGroups=new Set(allQuestions.filter(q=>derived.get(q.id).familiar).map(q=>q.group));
 if((mode==='chapter'||mode==='smart')&&!includeFamiliar)qs=qs.filter(q=>!familiarGroups.has(q.group));
 if(mode==='wrong')qs=qs.filter(q=>derived.get(q.id).wrong);if(mode==='review')qs=qs.filter(q=>derived.get(q.id).due||derived.get(q.id).uncertain);if(mode==='favorite')qs=qs.filter(q=>derived.get(q.id).favorite);
 qs=shuffle(qs);if(mode==='smart'||mode==='chapter'){const lastByGroup=new Map();for(const q of allQuestions){const t=derived.get(q.id).last?.ts||0;lastByGroup.set(q.group,Math.max(t,lastByGroup.get(q.group)||0))}const priority=q=>{const d=derived.get(q.id);return mode==='chapter'?(!lastByGroup.get(q.group)?0:d.wrong?1:d.uncertain?2:3):(d.due?0:d.wrong?1:d.uncertain?2:!lastByGroup.get(q.group)?3:4)};qs.sort((a,b)=>priority(a)-priority(b)||(lastByGroup.get(a.group)||0)-(lastByGroup.get(b.group)||0));}
 const groups=new Set();return qs.filter(q=>{const key=q.group||q.q;if(groups.has(key))return false;groups.add(key);return true});
}
function start(mode='smart',chapter='all',specific=null,requested=20,includeFamiliar=false){
 const qs=candidates(mode,chapter,specific,includeFamiliar);if(!qs.length){toast('当前没有未熟题。可在章节设置中勾选包含熟悉题，或先核对待定题。');return}
 const count=mode==='exam'?Math.min(10,qs.length):Math.max(1,Math.min(qs.length,Math.floor(Number(requested)||20)));
 let selected=qs.slice(0,count);
 if(mode==='exam'){
  const chapterOrder=shuffle([...new Set(qs.map(q=>q.chapterId))]);
  selected=chapterOrder.map(ch=>qs.find(q=>q.chapterId===ch)).filter(Boolean).slice(0,count);
  if(selected.length<count)selected.push(...qs.filter(q=>!selected.includes(q)).slice(0,count-selected.length));
 }
 if(store.session&&!store.session.finished){dialog('<h2>上次训练还没有结束</h2><p>开始新训练会替换未完成的题单，已提交记录会保留。</p><div class="actions"><button data-resume>继续上次训练</button><button id="replaceSession">开始新训练</button></div>');$('#replaceSession').onclick=()=>{$('#dialog').close();createSession(selected,mode)};return}
 createSession(selected,mode);
}
function chapterSettings(chapter){
 const name=allQuestions.find(q=>q.chapterId===chapter)?.chapter||'章节训练';
 dialog('<h2>'+esc(name)+'</h2><p>默认跳过已熟悉或已巩固的整个考点；未练考点优先，再练错题与拿不准的题。同一轮同考点只取一题。</p><label class="check-row"><input type="checkbox" id="includeFamiliar">包含已熟悉 / 已巩固题</label><p id="chapterAvailable"></p><label class="field">本轮题量<input id="chapterCount" type="number" min="1" step="1" value="'+(store.settings.chapterCount||10)+'"></label><div class="actions">'+[5,10,20].map(n=>'<button data-count-preset="'+n+'">'+n+'题</button>').join('')+'<button id="allChapter">全部可练</button><button id="beginChapter" class="primary">开始章节训练</button></div>');
 const refresh=()=>{const n=candidates('chapter',chapter,null,$('#includeFamiliar').checked).length;$('#chapterAvailable').textContent='本轮最多 '+n+' 题（按考点去重）';$('#chapterCount').max=Math.max(1,n);$('#chapterCount').value=n?Math.min(n,Math.max(1,Number($('#chapterCount').value)||10)):0;$('#beginChapter').disabled=!n;};
 $('#includeFamiliar').onchange=refresh;refresh();$$('[data-count-preset]').forEach(b=>b.onclick=()=>{$('#chapterCount').value=b.dataset.countPreset;refresh()});$('#allChapter').onclick=()=>{$('#chapterCount').value=$('#chapterCount').max;refresh()};
 $('#beginChapter').onclick=()=>{const n=Number($('#chapterCount').value),max=Number($('#chapterCount').max);if(!Number.isInteger(n)||n<1||n>max){toast('请输入1到'+max+'之间的整数题量');return}const include=$('#includeFamiliar').checked;store.settings.chapterCount=n;save();$('#dialog').close();start('chapter',chapter,null,n,include)};
}
function createSession(qs,mode){store.session={id:uid(),mode,ids:qs.map(q=>q.id),orders:Object.fromEntries(qs.map(q=>[q.id,store.settings.shuffle?shuffle(q.options.map((_,i)=>i)):q.options.map((_,i)=>i)])),responses:{},questionSnapshots:{},bankVersion:BANK.version,cursor:0,started:Date.now(),deadline:mode==='exam'?Date.now()+store.settings.minutes*60000:null,finished:false};tab='practice';save();render();window.scrollTo({top:0});}
function questionForSession(s,id){const live=byId.get(id),snapshot=s?.questionSnapshots?.[id];return snapshot&&live?{...live,...snapshot}:live;}
function current(){const s=store.session;if(!s)return null;const q=questionForSession(s,s.ids[s.cursor]);if(!q)return null;const response=s.responses[q.id]||(s.responses[q.id]={selected:[],unsure:false,submitted:false});return {s,q,r:response,order:s.orders[q.id]||q.options.map((_,i)=>i)};}
function record(q,r,s){const expected=answerFor(q);const result=grade(r.selected,expected);if(!result.correct||r.unsure)markFamiliar(q.id,false);emit('attempt',q.id,{selected:r.selected,expected:[...expected],correct:result.correct,kind:result.kind,missing:result.missing,extra:result.extra,unsure:!!r.unsure,mode:s.mode,questionRevision:q.revision||null,bankVersion:BANK.version,questionSnapshot:{q:q.q,options:[...q.options],answers:[...expected]}},s.id+'-'+q.id);r.submitted=true;r.result=result;}
function submit(){const c=current();if(!c||c.r.submitted)return;if(!c.r.selected.length){toast('请至少选择一项后提交');return}record(c.q,c.r,c.s);save();renderPractice();}
function finish(){const s=store.session;if(!s)return;if(s.mode==='exam'&&!s.finished){s.ids.forEach(id=>{const q=questionForSession(s,id);if(!q)return;const r=s.responses[id]||(s.responses[id]={selected:[],unsure:false});if(!r.submitted)record(q,r,s)})}s.finished=true;save();renderPractice();}
function renderPractice(){
 const s=store.session;if(!s){setTab('home');return}if(s.finished){renderResult();return}const c=current();if(!c){toast('部分自定义题已不可用，训练已结束');finish();return}const {q,r,order}=c;const exam=s.mode==='exam';const expected=answerFor(q),result=r.result;
 $('#main').innerHTML='<section class="session"><div class="session-meta"><button data-home>← 返回工作台</button><span>'+(exam?'模拟卷 · 10题 / 20分':'不定项训练')+'　'+(s.cursor+1)+' / '+s.ids.length+'</span>'+(exam?'<span class="timer" id="timer"></span>':'<span>进度自动保存</span>')+'</div><div class="progress"><i style="width:'+100*(s.cursor+1)/s.ids.length+'%"></i></div><div class="question-card"><span class="badge">'+esc(q.chapter)+'</span>'+badgeFor(q)+'<h2>'+esc(q.q)+'</h2><div id="options">'+order.map((orig,display)=>{const chosen=r.selected.includes(orig);let cls=chosen?'selected':'';let status='';if(r.submitted&&!exam){if(expected.includes(orig)){cls+=' correct';status=chosen?'选对':'漏选';if(!chosen)cls+=' missed'}else if(chosen){cls+=' wrong';status='多选'}}return '<button class="option '+cls+'" data-option="'+orig+'" aria-pressed="'+chosen+'" '+(r.submitted?'disabled':'')+'><span class="letter">'+'ABCD'[display]+'</span><span>'+esc(q.options[orig])+'</span>'+(status?'<span class="option-status">'+status+'</span>':'')+'</button>'}).join('')+'</div>'+(!r.submitted?'<label class="confidence"><input type="checkbox" id="unsure" '+(r.unsure?'checked':'')+'>这题拿不准，答对也加入复习</label>':'')+(r.submitted&&!exam?answerPanel(q,r,order):'')+'<div class="question-tools"><div class="actions">'+familiarControl(q)+'<button data-fav="'+esc(q.id)+'">'+(derived.get(q.id).favorite?'★ 已收藏':'☆ 收藏')+'</button><button data-note="'+esc(q.id)+'">记笔记</button><button data-issue="'+esc(q.id)+'">答案存疑</button></div><button data-evidence="'+esc(q.id)+'" '+(exam?'disabled':'')+'>查看教材原文</button></div></div><div class="practice-bar"><div class="actions"><button data-prev '+(s.cursor===0?'disabled':'')+'>上一题</button><button data-finish>'+(exam?'交卷':'结束本轮')+'</button></div><div class="actions">'+(!exam&&!r.submitted?'<button data-submit class="primary">提交答案</button>':'<button data-next class="primary">'+(s.cursor===s.ids.length-1?(exam?'交卷':'查看本轮结果'):'下一题 →')+'</button>')+'</div></div><div class="dot-grid">'+s.ids.map((id,i)=>'<button data-index="'+i+'" class="'+(i===s.cursor?'current ':'')+(s.responses[id]?.submitted||s.responses[id]?.selected?.length?'done':'')+'">'+(i+1)+'</button>').join('')+'</div><p class="muted">键盘：A—D选项，Enter提交或下一题。离开后可从“继续上次训练”恢复。</p></section>';
 if($('#unsure'))$('#unsure').onchange=e=>{r.unsure=e.target.checked;save()};updateTimer();
}
function explanationInOrder(text,order){const letter=i=>'ABCD'[order.indexOf(i)];return String(text||'').replace(/([ABCD])(?=[、，,；;。．项把将是与为属用对指说提选]|$)/g,(_,v)=>letter('ABCD'.indexOf(v))).replace(/前三项/g,[0,1,2].map(letter).join('、')+'项').replace(/后三项/g,[1,2,3].map(letter).join('、')+'项').replace(/前两项/g,[0,1].map(letter).join('、')+'项').replace(/后两项/g,[2,3].map(letter).join('、')+'项');}
function memoryTableHtml(q){
 const t=q.memoryTable;if(!t?.rows?.length)return '';
 return '<section class="memory-notes"><h4>速记对照</h4><table class="memory-table"><thead><tr>'+t.columns.map(c=>'<th scope="col">'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+t.rows.map(row=>'<tr>'+row.map(cell=>'<td>'+esc(cell)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'+(t.note?'<p class="memory-note">'+esc(t.note)+'</p>':'')+'<p class="memory-source">原书对照：PDF '+t.sourcePages.join('、')+' 页</p></section>';
}
function answerPanel(q,r,order){
 const expected=answerFor(q),letters=expected.map(i=>'ABCD'[order.indexOf(i)]).sort().join('、'),d=derived.get(q.id);
 const evidence=q.optionEvidence||[],reasons=new Set(evidence.map(e=>e.reason?.trim()).filter(Boolean)),table=memoryTableHtml(q);
 let overview=q.explain||'';
 for(const reason of reasons)if(evidence.filter(e=>e.reason?.trim()===reason).length===1)overview=overview.replaceAll(reason,'');
 overview=overview.replace(/^本题选(?:说法)?错误(?:的选项|项)。/,'').trim();
 const groups=new Map();order.forEach((orig,i)=>{const source=evidence[orig]?.sourceExcerpt;if(!source)return;const key=source.page+':'+source.text;if(!groups.has(key))groups.set(key,{...source,letters:[]});groups.get(key).letters.push('ABCD'[i])});
 // 没有具体理由就不生成A/B/C/D占位；简单对应题直接展示正确关系表。
 const detailed=table?'':order.map((orig,i)=>{
  const reason=evidence[orig]?.reason?.trim();if(!reason||evidence.filter(x=>x.reason?.trim()===reason).length>1||/^(?:本题)?(?:应选|不选|正确|错误)[。！.!]?$/.test(reason))return '';
  return '<p class="option-analysis"><b>'+ 'ABCD'[i]+'项：</b>'+esc(explanationInOrder(reason,order))+'</p>';
 }).join('');
 const shared=table?'':[...reasons].filter(reason=>evidence.filter(x=>x.reason?.trim()===reason).length>1&&reason!==q.explain).map(reason=>'<p>'+esc(explanationInOrder(reason,order))+'</p>').join('');
 return '<section class="answer-result '+(r.result.correct?'':'bad')+'"><h3>'+(r.result.correct?'完整选对':'本题0分 · '+esc(r.result.kind))+'</h3><p>本次显示顺序下的答案：<b>'+letters+'</b></p>'+(r.unsure?'<p>已加入“拿不准”复习队列。</p>':'')+table+(detailed?'<div class="guide concrete-analysis"><h4>选项说明</h4>'+detailed+'</div>':'')+(!table&&(overview||shared)?'<div class="guide"><h4>记忆要点</h4>'+(overview?'<p>'+esc(explanationInOrder(overview,order))+'</p>':'')+shared+'</div>':'')+(!table&&groups.size?'<details><summary>相关原文摘录 · 以教材扫描页为准</summary>'+[...groups.values()].map(s=>'<p><b>'+s.letters.join('、')+'项 · PDF第'+s.page+'页</b></p><blockquote>'+esc(s.text)+'</blockquote>').join('')+'</details>':'')+'<label class="field"><small>错因归类</small><select data-reason="'+esc(q.id)+'">'+['','概念不清','人物作品混淆','原句不熟','审题疏漏','漏判选项','答案存疑'].map(x=>'<option '+(d.tag===x?'selected':'')+'>'+esc(x||'请选择错因')+'</option>').join('')+'</select></label></section>';
}

function renderResult(){const s=store.session;const done=s.ids.map(id=>({q:questionForSession(s,id),r:s.responses[id]})).filter(x=>x.q&&x.r?.submitted);const correct=done.filter(x=>x.r.result?.correct).length;const total=s.mode==='exam'?s.ids.length:done.length;$('#main').innerHTML='<section class="session">'+head('本轮训练完成','完整选对才得分；把每次失分落实到具体选项。')+'<section class="panel"><span class="eyebrow">SESSION REVIEW</span><div class="score">'+(s.mode==='exam'?correct*2:correct)+' <small>/ '+(s.mode==='exam'?total*2:total)+(s.mode==='exam'?' 分':' 题全对')+'</small></div><p class="muted">已完成 '+done.length+' 题 · 漏选 '+done.filter(x=>x.r.result?.missing.length).length+' 题 · 多选 '+done.filter(x=>x.r.result?.extra.length).length+' 题 · 拿不准 '+done.filter(x=>x.r.unsure).length+' 题</p><div class="actions"><button data-home class="primary">回到工作台</button><button data-start="wrong">错题再练</button><button data-export>备份记录</button></div></section><section class="panel">'+done.map(({q,r})=>'<details><summary><span class="badge '+(r.result.correct?'':'bad')+'">'+(r.result.correct?'全对':esc(r.result.kind))+'</span>'+esc(q.q)+'</summary>'+answerPanel(q,r,s.orders[q.id])+ '<div class="actions"><button data-evidence="'+esc(q.id)+'">教材原文</button><button data-correct="'+esc(q.id)+'">核对答案</button></div></details>').join('')+'</section></section>';}
function updateTimer(){const s=store.session;if(tab!=='practice'||!s?.deadline||s.finished)return;const remaining=Math.max(0,Math.ceil((s.deadline-Date.now())/1000));if($('#timer'))$('#timer').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(remaining===0){toast('训练计时结束，已自动交卷');finish()}}
function go(delta){const s=store.session;if(!s)return;if(delta>0&&s.cursor===s.ids.length-1){if(s.mode==='exam')confirmFinish();else finish();return}s.cursor=Math.max(0,Math.min(s.ids.length-1,s.cursor+delta));save();renderPractice();window.scrollTo({top:0})}
function confirmFinish(){const s=store.session;if(s.mode!=='exam'){finish();return}const empty=s.ids.filter(id=>!s.responses[id]?.selected?.length).length;dialog('<h2>确认交卷</h2><p>'+(empty?'还有 '+empty+' 题未作答，将按0分计入本轮。':'全部题目已作答，交卷后统一查看解析。')+'</p><button id="confirmFinish" class="primary">确认交卷</button>');$('#confirmFinish').onclick=()=>{$('#dialog').close();finish()};}
function evidenceDialog(id,selectedPage){const q=byId.get(id);if(!q)return;const b=q.bookEvidence;const pages=[...new Set([...(b?.pages||[b?.page||7]),...(q.memoryTable?.sourcePages||[])])].filter(n=>Number.isInteger(n)&&n>=1&&n<=456);const p=pages.includes(selectedPage)?selectedPage:pages[0];const image=(location.protocol==='file:'?'./辅助资料/教材页面/':'./book-pages/')+'教材-'+String(p).padStart(3,'0')+'.jpg';dialog('<h2>教材原文 · PDF第'+p+'页</h2><p>'+esc(BANK.textbook.title)+'；PDF页码与印刷页码不同。</p><div class="actions">'+pages.map(n=>'<button data-bookpage="'+n+'" data-question="'+esc(id)+'">PDF第'+n+'页</button>').join('')+'</div><p>'+esc(b?.kind||'教材对照')+'</p><img style="max-width:100%;height:auto" src="'+image+'" alt="教材扫描页"><p><a href="'+image+'" target="_blank" rel="noopener">单独打开扫描页</a></p><details><summary>本页OCR文字（识别可能有误，以扫描为准）</summary><div class="note-text">'+esc(BANK.textbook.text[p-1])+'</div></details>');}

function noteDialog(id){const d=derived.get(id);dialog('<h2>我的笔记</h2><p>'+esc(byId.get(id).q)+'</p><textarea id="myNote" maxlength="5000" placeholder="写下错因、教材原句或辨析要点…">'+esc(d.note)+'</textarea><div class="dialog-actions"><button id="saveNote" class="primary">保存笔记</button></div>');$('#saveNote').onclick=()=>{emit('note',id,{value:$('#myNote').value});$('#dialog').close();toast('笔记已保存');render()};}
function correctionDialog(id){const q=byId.get(id),d=derived.get(id);dialog('<h2>核对答案</h2><p>'+esc(q.q)+'</p><div class="callout">请依据你提供的《艺术学概论》教材原文确认。保存的是你自己的核对答案，不会被标成官方答案。</div>'+q.options.map((x,i)=>'<label class="check-row"><input type="checkbox" name="correction" value="'+i+'" '+(d.correction?.answers.includes(i)?'checked':'')+'><span>'+'ABCD'[i]+' · '+esc(x)+'</span></label>').join('')+'<label class="field"><span>核对依据 / 教材页码（必填）</span><textarea id="correctionReason" maxlength="3000">'+esc(d.correction?.reason||'')+'</textarea></label><div class="actions"><button data-evidence="'+esc(id)+'">查看教材原文</button><button id="saveCorrection" class="primary">确认并启用此答案</button></div>');$('#saveCorrection').onclick=()=>{const answers=$$('input[name="correction"]:checked').map(x=>Number(x.value));const reason=$('#correctionReason').value.trim();if(!answers.length||!reason){toast('请选定答案并填写核对依据');return}emit('correction',id,{answers,reason,bankVersion:BANK.version,questionRevision:q.revision||null});emit('issue',id,{value:false});$('#dialog').close();toast('已保存你的核对答案');render()};}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function exportBackup(){download('艺术刷题-学习备份-'+nowDay()+'.json',{format:'zju-art-choice-backup',version:1,exportedAt:new Date().toISOString(),bankVersion:BANK.version,events:store.events.map(({_synced,...e})=>e)});}
function validQuestion(q){return q&&typeof q.id==='string'&&q.id.length<500&&typeof q.q==='string'&&q.q.length<10000&&Array.isArray(q.options)&&q.options.length===4&&q.options.every(x=>typeof x==='string'&&x.length<10000)&&Array.isArray(q.answers)&&q.answers.every(a=>Number.isInteger(a)&&a>=0&&a<4);}
function validEvent(e){if(!e||typeof e.id!=='string'||e.id.length>160||typeof e.qid!=='string'||e.qid.length>500||!allowedEvents.has(e.type)||typeof e.ts!=='number'||!Number.isFinite(e.ts)||!e.data||typeof e.data!=='object'||JSON.stringify(e.data).length>40000)return false;if(e.type==='custom')return validQuestion(e.data.question);if(e.type==='correction')return Array.isArray(e.data.answers)&&e.data.answers.length>0&&e.data.answers.every(x=>Number.isInteger(x)&&x>=0&&x<4)&&typeof e.data.reason==='string';if(e.type==='attempt')return Array.isArray(e.data.selected)&&e.data.selected.every(x=>Number.isInteger(x)&&x>=0&&x<4)&&typeof e.data.correct==='boolean';return true;}
function mergeEvents(events,synced=false){const existing=new Map(store.events.map(e=>[e.id,e]));let added=0;for(const e of events){if(!validEvent(e))continue;if(existing.has(e.id)){if(synced)existing.get(e.id)._synced=true;continue}const copy={id:e.id,qid:e.qid,type:e.type,ts:e.ts,data:e.data,_synced:synced};store.events.push(copy);existing.set(copy.id,copy);added++;}return added;}
$('#importFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>25_000_000)throw Error('文件过大，请使用25MB以内的学习备份');const data=JSON.parse(await f.text());let n=0;if(data.format==='zju-art-choice-backup'){if(data.version!==1||!Array.isArray(data.events)||data.events.length>100000||data.events.some(e=>!validEvent(e)))throw Error('备份格式或事件内容无效，未导入');n=mergeEvents(data.events)}else if(Array.isArray(data.quiz)){
 const events=[],stamp=Date.now();for(const old of data.quiz){const answers=old.answers||[old.answer];const q={...old,answers,origin:'从学习台迁移',flags:[],status:answers.length?'inherited':'pending',tags:['迁移题'],chapter:old.chapter||'迁移题',chapterId:old.chapterId||'migrated',group:old.q,explain:old.explain||'原学习台未提供解析'};if(!validQuestion(q))continue;const known=byId.get(q.id);if(!known||JSON.stringify([known.q,known.options,known.answers])!==JSON.stringify([q.q,q.options,q.answers]))events.push({id:'migrate-q-'+uid(),qid:q.id,type:'custom',ts:stamp,data:{question:q}});if((data.wrong||[]).includes(q.id))events.push({id:'legacy-wrong-'+q.id,qid:q.id,type:'legacywrong',ts:stamp,data:{}});if((data.favorites||[]).includes(q.id))events.push({id:'legacy-favorite-'+q.id,qid:q.id,type:'favorite',ts:stamp,data:{value:true}});}n=mergeEvents(events)
 }else throw Error('请选择本程序备份或原学习台导出的完整数据');rebuild();await persist();scheduleSync();render();toast('已合并 '+n+' 条记录，现有数据已保留');}catch(err){toast('导入失败：'+err.message)}};
function scheduleSync(){clearTimeout(syncTimer);syncTimer=setTimeout(()=>sync(false),3500);}
function updateSync(text){syncText=text;$('#sync').textContent=text;}
async function sync(manual=false){const ready=location.protocol==='file:'||!!navigator.serviceWorker?.controller;updateSync(ready?'本机保存 · 离线已就绪':'本机保存 · 正在准备离线');if(manual)toast(ready?'独立版无需登录，记录保存在本设备；跨设备请导出、导入备份':'离线内容仍在准备，请保持联网，直到显示离线已就绪')}
$('#sync').onclick=()=>sync(true);window.addEventListener('online',()=>sync(false));document.addEventListener('visibilitychange',()=>{if(document.hidden)persist();else sync(false)});window.addEventListener('pagehide',()=>persist());
