 if(b.dataset.pagePractice){const row=BANK.bookAudit.pages.find(x=>x.page===Number(b.dataset.pagePractice));$('#dialog').close();start('chapter','all',row.questionIds.map(x=>byId.get(x)).filter(Boolean),10);return}
 if(b.hasAttribute('data-open-guide')){setTab('guide');return}if(b.dataset.start){if($('#dialog').open)$('#dialog').close();start(b.dataset.start);return}
 if(b.hasAttribute('data-chapter-start')){chapterSettings(b.dataset.chapterStart);return}
 if(b.dataset.familiar){const id=b.dataset.familiar;markFamiliar(id,!derived.get(id).familiar);render();toast(derived.get(id).familiar?'此考点及其变式已标熟悉，章节训练将跳过':'已取消熟悉，此考点可重新训练');return}
 if(b.dataset.bookpage){evidenceDialog(b.dataset.question,Number(b.dataset.bookpage));return}
 if(b.hasAttribute('data-resume')){if($('#dialog').open)$('#dialog').close();tab='practice';render();return}
