(async()=>{await load();store.events=store.events.filter(validEvent);preserveQuestionHistory();rebuild();if(store.session&&store.session.ids.some(id=>!byId.has(id))){store.archivedSession=store.session;store.session=null}if(store.bankVersion!==BANK.version){store.bankVersion=BANK.version;toast('解析已更新；原做题记录、收藏、笔记和熟悉标记保留')}render();void persist();if(location.protocol!=='file:'&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});sync(false);setInterval(updateTimer,1000);setInterval(()=>sync(false),60000);})().catch(err=>{document.getElementById('main').innerHTML='<section class=panel><h2>启动未完成</h2><p>请用 Safari 打开，关闭其他刷题窗口后重新载入。原学习记录未删除。</p><p>'+esc(err.message)+'</p><button onclick=location.reload()>重新载入</button></section>'});



let sourceKind='all';
function sourceRecord(id){return [...store.events].filter(e=>e.type==='sourceReview'&&e.qid===id).sort((a,b)=>a.ts-b.ts||a.id.localeCompare(b.id)).at(-1)?.data||{state:'new',note:''};}
function sourceImage(name){return (location.protocol==='file:'?'./辅助资料/网盘导入20261026/':'./source-pages/')+encodeURIComponent(name);}
function sourceBankPage(){
 const bank=BANK.externalBank;if(!bank)return head('网盘题库','暂无资料');
 const items=bank.items.filter(x=>(sourceKind==='all'||sourceKind==='wrong'&&sourceRecord(x.id).state==='wrong'||x.kind===sourceKind)&&(!filterSearch||(x.title+x.text+sourceRecord(x.id).note).includes(filterSearch)));
 return head('网盘题库','原图自测 · 选择题与填空题 · 本机记录可备份')+'<section class="panel"><p>已收录60页选择题、12页填空题及12页填空答案。选择题正文标称550题，分享标题标称500题。</p><p class="muted">此区是待核资料，不计入已核定题量或考试得分。资料答案与第五版原书冲突时，以原书为准；OCR仅辅助检索。选择题先看灰度原图自测，再展开蓝色参考答案；填空题与答案分开展示。</p><div class="actions"><button data-source-download>下载全部原图供离线使用</button><button data-export>备份全部学习记录</button></div></section><div class="chips">'+[['all','全部'],['choice','选择题'],['fill','填空题'],['wrong','待复习']].map(([id,title])=>'<button data-source-filter="'+id+'" class="chip '+(id===sourceKind?'active':'')+'">'+title+'</button>').join('')+'</div><div class="filters"><input id="search" aria-label="检索网盘资料" placeholder="搜索题目、作品、人物或错题笔记…" value="'+esc(filterSearch)+'"></div><section class="panel">'+(items.length?items.slice((viewPage-1)*20,viewPage*20).map(x=>{const r=sourceRecord(x.id);return '<article class="list-row"><h3>'+esc(x.title)+'</h3><p>'+({new:'尚未自测',wrong:'本页有待复习题目',done:'本页已完成自测'}[r.state]||'尚未自测')+'</p>'+(r.note?'<p class="note-text">'+esc(r.note)+'</p>':'')+'<button data-source-page="'+x.id+'">打开原题自测</button></article>'}).join(''):'<p>没有匹配的资料</p>')+'</section>'+pager(items.length);
}
function openSourcePage(id){
 const items=BANK.externalBank.items,x=items.find(x=>x.id===id);if(!x)return;
 const r=sourceRecord(id),siblings=items.filter(v=>v.kind===x.kind),pos=siblings.findIndex(v=>v.id===id);
 dialog('<h2>'+esc(x.title)+'</h2><p>资料参考答案尚未逐题核定，不参与计分。可在笔记中记下本页具体错题号；原书核对优先。</p><div class="actions">'+(pos?'<button data-source-page="'+siblings[pos-1].id+'">上一页</button>':'')+(pos<siblings.length-1?'<button data-source-page="'+siblings[pos+1].id+'">下一页</button>':'')+'</div><img style="max-width:100%;height:auto;'+(x.kind==='choice'?'filter:grayscale(1) contrast(3)':'')+'" src="'+sourceImage(x.image)+'" alt="'+esc(x.title)+'题目"><details><summary>展开资料参考答案（未核定）</summary><img style="max-width:100%;height:auto" src="'+sourceImage(x.answerImage)+'" alt="原资料参考答案"></details><label>本页错题号、所选答案、错因或原书核对笔记<textarea id="sourceNote" maxlength="5000">'+esc(r.note)+'</textarea></label><label>自测状态<select id="sourceState"><option value="new">尚未完成</option><option value="wrong">本页有题待复习</option><option value="done">本页已自测</option></select></label><div class="actions"><button id="sourceSave" class="primary">保存本页记录</button><button data-book-audit>打开原书核查</button></div>');
 $('#sourceState').value=r.state;$('#sourceSave').onclick=()=>{emit('sourceReview',id,{state:$('#sourceState').value,note:$('#sourceNote').value});$('#dialog').close();render();toast('本页记录已保存，可随学习备份迁移')};
}
async function cacheSourceBank(button){
 const files=[...new Set(BANK.externalBank.items.flatMap(x=>[x.image,x.answerImage]))];button.disabled=true;let done=0,failed=0;
 for(const file of files){try{const response=await fetch(sourceImage(file));if(!response.ok)throw Error('下载失败');await response.arrayBuffer();done++}catch{failed++}button.textContent='已读取 '+done+' / '+files.length+' 张';}
 button.disabled=false;button.textContent=failed?'有 '+failed+' 张未读取，点此重试':'84张原图已读取';toast(location.protocol==='file:'?'原图已就绪':failed?'部分原图未缓存，请联网重试':navigator.serviceWorker?.controller?'原图已读取并交由离线缓存保存':'请等待离线准备就绪后再读取一次');
}

function preserveQuestionHistory(){
 const previous=BANK.questionRevisionHistory;if(!previous)return;
 for(const event of store.events){const old=previous.questions[event.qid];if(event.type==='attempt'&&old&&!event.data.questionSnapshot){event.data.questionSnapshot={q:old.q,options:[...old.options],answers:[...old.answers]};event.data.questionRevision=old.revision;event.data.bankVersion=event.data.bankVersion||previous.fromVersion;}}
 if(store.session&&store.session.bankVersion!==BANK.version){const needsPrevious=!store.session.bankVersion||store.session.bankVersion===previous.fromVersion;store.session.questionSnapshots=store.session.questionSnapshots||{};if(needsPrevious)for(const id of store.session.ids){if(previous.questions[id]&&!store.session.questionSnapshots[id])store.session.questionSnapshots[id]=previous.questions[id];}store.session.bankVersion=BANK.version;}
}

